/* Node.js example: Cache-Aside with Redis and singleflight to prevent thundering herd */
const Redis = require('ioredis');
const redis = new Redis();
const inflight = new Map();

async function getItem(key) {
  const cached = await redis.get(key);
  if (cached) return JSON.parse(cached);

  if (inflight.has(key)) {
    return inflight.get(key); // return the in-flight promise
  }

  const promise = (async () => {
    try {
      const item = await db.fetch(key); // expensive
      if (item) await redis.set(key, JSON.stringify(item), 'EX', 300);
      return item;
    } finally {
      inflight.delete(key);
    }
  })();

  inflight.set(key, promise);
  return promise;
}
